# Zika virus (NC_012532.1), complete genome - Family: Flaviviridae
genome = ""

# Dengue virus type 2 (NC_001474.2), complete genome - Family: Flaviviridae
genome_d2 = ""
genome_b3 = genome_d2  # alias for backward compatibility

# Use 3 restriction enzymes(name, reseq, cleavage site)

EcoRI = "gaattc"

BamHi = "ggatcc"

HindIII = "aagctt"

segments = []


def applyRestrictionEnzyme(sequence, enzyme, segments):
    copy_gen = sequence
    j = 0
    while (j <= len(copy_gen) - 6):
        if (copy_gen[j:j + 6] == enzyme):
            segments.append(copy_gen[:j + 1])
            copy_gen = copy_gen[j + 1:]
            j = 0
        else:
            j += 1
    segments.append(copy_gen)


applyRestrictionEnzyme(genome, EcoRI, segments)

print(segments)

import math
import matplotlib.pyplot as plt


def electrophoresis(sequence, genome_name, enzymes):
    ladder = [10000, 8000, 6000, 5000, 4000, 3000, 2000, 1500, 1000, 500, 250, 100]
    lanes = [("Ladder", ladder)]
    for name, enzyme in enzymes:
        frags = []
        applyRestrictionEnzyme(sequence, enzyme, frags)
        lanes.append((name, [len(f) for f in frags]))
        print(genome_name, name, "fragment lengths:", lanes[-1][1])

    fig, ax = plt.subplots(figsize=(6, 7))
    ax.set_facecolor("black")
    for x, (lane_name, sizes) in enumerate(lanes):
        ax.add_patch(plt.Rectangle((x - 0.3, 4.15), 0.6, 0.08, color="gray"))
        for s in sizes:
            y = math.log10(s)
            ax.add_patch(plt.Rectangle((x - 0.3, y - 0.012), 0.6, 0.024, color="white"))
            if lane_name == "Ladder":
                ax.text(x - 0.4, y, str(s), color="white", ha="right", va="center", fontsize=7)
            else:
                ax.text(x + 0.35, y, str(s), color="cyan", ha="left", va="center", fontsize=7)

    ax.set_xlim(-1, len(lanes))
    ax.set_ylim(1.6, 4.3)
    ax.set_xticks(range(len(lanes)))
    ax.set_xticklabels([name for name, _ in lanes])
    ax.set_yticks([])
    ax.set_title(genome_name)
    plt.tight_layout()
    plt.savefig(f"gel_{genome_name.replace(' ', '_')}.png", dpi=150)
    plt.show()


enzymes = [("EcoRI", EcoRI), ("BamHI", BamHi), ("HindIII", HindIII)]
electrophoresis(genome, "Zika virus", enzymes)
electrophoresis(genome_d2, "Dengue virus 2", enzymes)